"""Helper utilities."""
import re

def parse_duration(s):
    """Parse duration string (e.g. '1h30m15s') to float seconds."""
    pattern = r'(?:(?P<hours>\d+)h)?(?:(?P<minutes>\d+)m)?(?:(?P<seconds>\d+)s)?'
    match = re.fullmatch(pattern, s)
    if not match:
        raise ValueError(f"Invalid duration format: {s}")

    parts = match.groupdict()
    total = 0.0
    if parts['hours']:
        total += int(parts['hours']) * 3600
    if parts['minutes']:
        total += int(parts['minutes']) * 60
    if parts['seconds']:
        total += int(parts['seconds'])

    return float(total)
